import time
from robot.api import logger
from robot.utils.robottime import secs_to_timestr, timestr_to_secs
from taf.ul.power_ue.devices.device_class import PowerUeDevice
from ute_common_abstract_core.aliases_registry import aliases_registry
from taf.ul.power_ue.exception import VerifyAttachTimeout, VerifyThroughputError


class TafUeDevice(PowerUeDevice):
    """
    PowerUeDevice API abstract base class. Parent class for implementation.
    """

    def __init__(self, ue_config, tl=None, **kwargs):
        super(TafUeDevice, self).__init__(ue_config, **kwargs)
        self.tl = tl

    def prepare(self, ue_alias, **kwargs):
        """
        Prepare UE for L3 call.
        """
        self.ue_alias = ue_alias
        if ue_alias not in aliases_registry():
            self.taf_ue.require_ue(
                ue_alias=ue_alias, capabilities=self.ue_config.capabilities
            )

    def teardown(self):
        """
        Teardown UE for L3 call.
        """
        self._teardown()

    def attach(self, timeout=30, **kwargs):
        """
        Attach UE for L3 call.
        """
        self.taf_ue.attach_ue(ue_alias=self.ue_alias, timeout=int(timeout))

    def create_pdu_session(self, **kwargs):
        """
        create PDU sesson which is needed when use taf.ue.at.
        """
        self.taf_ue.create_pdu_session(self.ue_alias)

    def release_pdu_session(self, **kwargs):
        """
        release PDU sesson which is needed when use taf.ue.at.
        """
        self.taf_ue.release_pdu_session(self.ue_alias)

    def verify_attach(
        self, timeout=60, apn=None, pci=None, cell_id=None, ue_info_dict=None, **kwargs
    ):
        """
        Verify attach result when plugin verify itself insufficiently.
        when use taf.ue.at do attach, cell_id can be get by get_ue_info
        """
        if ue_info_dict is None:
            ue_info_dict = {"pci": "PCI", "ips": "IPS"}
        start_time = time.time()
        flags = (False, False, False)
        while time.time() - start_time < float(timeout):
            ue_info = {}
            for k in ue_info_dict:
                ue_info[k] = self.taf_ue.get_ue_info(self.ue_alias, ue_info_dict[k])
            flags = self._is_ue_info_valid(ue_info, apn, pci, cell_id)
            if all(flags):
                break
        else:
            raise VerifyAttachTimeout(
                "IP check: {}\n"
                "PCI check: {}\n"
                "CELL_ID check: {}\n".format(flags[0], flags[1], flags[2])
            )

    def reboot(self, timeout=180, **kwargs):
        """
        reboot UE for L3 call.
        """
        self.taf_ue.reboot_ue(ue_alias=self.ue_alias, timeout=int(timeout))

    def detach(self, **kwargs):
        """
        Detach UE for L3 call.
        """
        self.taf_ue.detach_ue(ue_alias=self.ue_alias)

    def start_traffic(
        self,
        dt_name,
        direction,
        duration=10,
        throughput=10.0,
        protocol="udp",
        iperf_port=None,
        check_dt_alive_timeout=None,
        iperf_options=None,
        apn=None,
        **kwargs
    ):
        """
        Start data transfer for L3 call.
        """
        if isinstance(duration, str):
            duration = int(duration)
        duration = secs_to_timestr(duration)
        throughput = self._format_throughput_unit_to_mbps(throughput=throughput)
        iperf_options = iperf_options or {}
        self.taf_ue.start_data_transfer(
            dt_name=dt_name,
            ue_alias=self.ue_alias,
            direction=direction,
            duration=duration,
            throughput=throughput,
            protocol=protocol,
            port=iperf_port,
            apn=apn,
            **iperf_options
        )
        check_dt_alive_timeout = check_dt_alive_timeout or 5
        time.sleep(check_dt_alive_timeout)
        self.taf_ue.check_data_transfer_is_alive(dt_name=dt_name)

    def stop_traffic(self, dt_name, **kwargs):
        """
        Stop data transfer for L3 call.
        """
        self.taf_ue.stop_data_transfer(dt_name=dt_name)

    def check_unidirectional_throughput(
        self,
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        omit=60,
        end=660,
        **kwargs
    ):
        if isinstance(omit, str):
            omit = timestr_to_secs(omit)
        if isinstance(end, str):
            end = timestr_to_secs(end)
        average_tolerance = self._get_tolerance_decimal(tolerance=average_tolerance)
        minimum_tolerance = self._get_tolerance_decimal(tolerance=minimum_tolerance)
        return self._check_iperf_throughput(
            dt_name=dt_name,
            omit=omit,
            end=end,
            theoretical_throughput=theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
        )

    def check_bidirectional_throughput(
        self,
        dt_name,
        ul_theoretical_throughput="5",
        dl_theoretical_throughput="5",
        average_tolerance="0.95",
        minimum_tolerance="0.8",
        omit=60,
        end=660,
        **kwargs
    ):
        if isinstance(omit, str):
            omit = timestr_to_secs(omit)
        if isinstance(end, str):
            end = timestr_to_secs(end)
        average_tolerance = self._get_tolerance_decimal(tolerance=average_tolerance)
        minimum_tolerance = self._get_tolerance_decimal(tolerance=minimum_tolerance)
        return self._check_bidirection_iperf_throughput(
            dt_name=dt_name,
            omit=omit,
            end=end,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            average_tolerance=average_tolerance,
            minimum_tolerance=minimum_tolerance,
        )

    def _check_iperf_throughput(
        self,
        dt_name,
        omit,
        end,
        theoretical_throughput,
        average_tolerance,
        minimum_tolerance,
    ):
        average_theoretical_throughput = (
            theoretical_throughput
            * self._get_tolerance_decimal(tolerance=average_tolerance)
        )
        minimum_theoretical_throughput = (
            theoretical_throughput
            * self._get_tolerance_decimal(tolerance=minimum_tolerance)
        )

        try:
            minimum_throughput = self._format_throughput_unit_to_mbps(
                throughput=average_theoretical_throughput
            )
            self.taf_ue.verify_average_throughput(
                dt_name=dt_name, tput_min=minimum_throughput, omit=omit, end=end
            )
        except Exception:
            pass

        result = self.__format_data_transfer_statistics_to_strandard_dict_format(
            self.taf_ue.get_data_transfer_statistics(dt_name=dt_name, omit=omit, end=end)
        )
        logger.info(result)
        average_throughput = self._calcullate_throughput_mbps_value(
            throughput=result["average_statistics"]
        )
        minimum_throughput = self._calcullate_throughput_mbps_value(
            throughput=result["minimum_statistics"]
        )
        if average_throughput < average_theoretical_throughput:
            raise VerifyThroughputError(
                msg="get average throughput {} less than {}".format(
                    average_throughput, average_theoretical_throughput
                ),
                throughput=result,
            )
        if minimum_throughput < minimum_theoretical_throughput:
            raise VerifyThroughputError(
                msg="get minimum throughput {} less than {}".format(
                    minimum_throughput, minimum_theoretical_throughput
                ),
                throughput=result,
            )
        return result

    def _check_bidirection_iperf_throughput(
        self,
        dt_name,
        omit,
        end,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        average_tolerance,
        minimum_tolerance,
    ):
        ul_throughput = self._format_throughput_unit_to_mbps(
            ul_theoretical_throughput * self._get_tolerance_decimal(average_tolerance)
        )
        dl_throughput = self._format_throughput_unit_to_mbps(
            dl_theoretical_throughput * self._get_tolerance_decimal(average_tolerance)
        )
        target = "ul:{ul},dl:{dl}".format(ul=ul_throughput, dl=dl_throughput)

        try:
            self.taf_ue.verify_average_throughput(
                dt_name=dt_name, tput_min=target, omit=omit, end=end
            )
        except Exception:
            pass
        result = self.taf_ue.get_data_transfer_statistics(dt_name=dt_name)
        logger.info(result)
        self.__check_bidirection_iperf_average_throughput(
            data_transfer_statistics=result,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            average_tolerance=average_tolerance,
        )
        self.__check_bidirection_iperf_minimum_throughput(
            data_transfer_statistics=result,
            ul_theoretical_throughput=ul_theoretical_throughput,
            dl_theoretical_throughput=dl_theoretical_throughput,
            minimum_tolerance=minimum_tolerance,
        )
        return result

    def __check_bidirection_iperf_average_throughput(
        self,
        data_transfer_statistics,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        average_tolerance,
    ):
        ul_theoretical_average = (
            ul_theoretical_throughput * self._get_tolerance_decimal(average_tolerance)
        )
        dl_theoretical_average = (
            dl_theoretical_throughput * self._get_tolerance_decimal(average_tolerance)
        )
        ul_average_throughput = self._calcullate_throughput_mbps_value(
            throughput=data_transfer_statistics["ul"]["average_statistics"]
        )
        dl_average_throughput = self._calcullate_throughput_mbps_value(
            throughput=data_transfer_statistics["dl"]["average_statistics"]
        )
        if (
            ul_average_throughput < ul_theoretical_average
            and dl_average_throughput < dl_theoretical_average
        ):
            raise VerifyThroughputError(
                msg="Both direction average throughput ul:{} dl:{} less than expected ul:{} dl:{}".format(
                    ul_average_throughput,
                    dl_average_throughput,
                    ul_theoretical_average,
                    dl_theoretical_average,
                ),
                throughput=data_transfer_statistics,
            )
        if ul_average_throughput < ul_theoretical_average:
            raise VerifyThroughputError(
                msg="get UL average throughput {} less than {}".format(
                    ul_average_throughput, ul_theoretical_average
                ),
                throughput=data_transfer_statistics,
            )
        if dl_average_throughput < dl_theoretical_average:
            raise VerifyThroughputError(
                msg="get DL average throughput {} less than {}".format(
                    dl_average_throughput, dl_theoretical_average
                ),
                throughput=data_transfer_statistics,
            )

    def __check_bidirection_iperf_minimum_throughput(
        self,
        data_transfer_statistics,
        ul_theoretical_throughput,
        dl_theoretical_throughput,
        minimum_tolerance,
    ):
        ul_theoretical_minimum = (
            ul_theoretical_throughput * self._get_tolerance_decimal(minimum_tolerance)
        )
        dl_theoretical_minimum = (
            dl_theoretical_throughput * self._get_tolerance_decimal(minimum_tolerance)
        )
        ul_minimum_throughput = self._calcullate_throughput_mbps_value(
            throughput=data_transfer_statistics["ul"]["minimum_statistics"]
        )
        dl_minimum_throughput = self._calcullate_throughput_mbps_value(
            throughput=data_transfer_statistics["dl"]["minimum_statistics"]
        )
        if (
            ul_minimum_throughput < ul_theoretical_minimum
            and dl_minimum_throughput < dl_theoretical_minimum
        ):
            raise VerifyThroughputError(
                msg="Both direction minimum throughput ul:{} dl:{} less than expected ul:{} dl:{}".format(
                    ul_minimum_throughput,
                    dl_minimum_throughput,
                    ul_theoretical_minimum,
                    dl_theoretical_minimum,
                ),
                throughput=data_transfer_statistics,
            )
        if ul_minimum_throughput < ul_theoretical_minimum:
            raise VerifyThroughputError(
                msg="get UL minimum throughput {} less than {}".format(
                    ul_minimum_throughput, ul_theoretical_minimum
                ),
                throughput=data_transfer_statistics,
            )
        if dl_minimum_throughput < dl_theoretical_minimum:
            raise VerifyThroughputError(
                msg="get DL minimum throughput {} less than {}".format(
                    dl_minimum_throughput, dl_theoretical_minimum
                ),
                throughput=data_transfer_statistics,
            )

    @staticmethod
    def __format_data_transfer_statistics_to_strandard_dict_format(statistics):
        if isinstance(statistics, str):
            summary = statistics.split(";")[0]
            details = statistics.split(";")[-1]
            return {
                "average_statistics": "{}bits/sec".format(summary.split(",")[0]),
                "minimum_statistics": "{}bits/sec".format(summary.split(",")[1]),
                "maximum_statistics": "{}bits/sec".format(summary.split(",")[2]),
                "list_of_bps_per_interval": details,
            }
        return statistics

    @staticmethod
    def _is_ue_ip_valid(ue_info, apn=None):
        if "ips" in ue_info:
            if apn:
                ip_flag = len(ue_info["ips"][apn]) > 0
            else:
                ip_flag = any(len(i) > 0 for i in ue_info["ips"].values())
            logger.info(
                "ue ips {}".format(ue_info["ips"])
                if ip_flag
                else "invalid ips {}".format(ue_info["ips"])
            )
        elif "ip" in ue_info:
            ue_ip = ue_info["ip"] or ""
            ip_flag = ue_ip != "127.0.0.0" and len(ue_ip) > 0
            logger.info(
                "ue ip {}".format(ue_ip) if ip_flag else "invalid ip {}".format(ue_ip)
            )
        else:
            logger.info("Do not have IP check point in {}".format(ue_info))
            ip_flag = True
        return ip_flag

    @staticmethod
    def _is_ue_pci_valid(ue_info, pci=0):
        if "pci" in ue_info:
            pci = pci or 0
            attach_pci = (
                ue_info["pci"]["pci"] if "pci" in ue_info["pci"] else ue_info["pci"]
            )
            logger.info("ue pci is {}".format(attach_pci))
            pci_flag = str(attach_pci) == str(pci) if int(pci) else True
            logger.info("Attached PCI: {}, Expected PCI: {}".format(attach_pci, pci))
        else:
            logger.info("Do not have PCI check point in {}".format(ue_info))
            pci_flag = True
        return pci_flag

    @staticmethod
    def _is_ue_cell_id_valid(ue_info, cell_id=0):
        if "cell_id" in ue_info:
            cell_id = cell_id or 0
            attach_cell_id = ue_info["cell_id"]
            logger.info("ue attached celll_id is {}".format(attach_cell_id))
            cell_id_flag = str(attach_cell_id) == str(cell_id) if int(cell_id) else True
            logger.info(
                "Attached CELL_ID: {}, Expected CELL_ID: {}".format(
                    attach_cell_id, cell_id
                )
            )
        else:
            logger.info("Do not have cell_id check point in {}".format(ue_info))
            cell_id_flag = True
        return cell_id_flag

    def _is_ue_info_valid(self, ue_info, apn, pci, cell_id):
        return (
            self._is_ue_ip_valid(ue_info, apn),
            self._is_ue_pci_valid(ue_info, pci),
            self._is_ue_cell_id_valid(ue_info, cell_id),
        )
